package com.cryptoloan.audit.adapters.out;import com.cryptoloan.audit.domain.*;import java.util.List;import org.springframework.stereotype.Component;@Component class AuditRepositoryAdapter implements AuditRepositoryPort{private final SpringDataAuditRepository repo;AuditRepositoryAdapter(SpringDataAuditRepository repo){this.repo=repo;}public void append(AuditEvent event){AuditJpaEntity e=new AuditJpaEntity();e.actor=event.actor();e.action=event.action();e.resource=event.resource();e.details=event.details();e.occurredAt=event.occurredAt();repo.save(e);}public List<AuditEvent>recent(){return repo.findTop200ByOrderByOccurredAtDesc().stream().map(e->new AuditEvent(e.id,e.actor,e.action,e.resource,e.details,e.occurredAt)).toList();}}

